class Solution {
    public boolean containsNearbyDuplicate(int[] nums, int k) {
        for (int i = 0; i < nums.length; i++) {
            int end = Math.min(nums.length - 1, i + k);
            for (int j = i + 1; j <= end; j++) {
                if (nums[i] == nums[j]) return true;
            }
        }
        return false;
    }
}

